        // Simulate verbose format
        let verbose = format!(
            r#"{{"last_modified":{},"seen_files":{:?},"version":{},"enabled":{},"filter_pattern":{:?}}}"#,
            state.last_modified.unwrap(),
            state.seen_files,
            state.version,
            state.enabled,
            state.filter_pattern,
        );

