    // Old pattern: up to 5 allocations
    let mut old_result = String::new();
    old_result.push_str("query");      // alloc 1
    old_result.push(':');               // may realloc
    old_result.push_str("agent");      // may realloc
    old_result.push(':');               // may realloc
    old_result.push_str("30");         // may realloc

    // New pattern: 1 allocation
    let size = "query".len() + 1 + "agent".len() + 1 + "30".len();
    let mut new_result = String::with_capacity(size);
    new_result.push_str("query");
    new_result.push(':');
    new_result.push_str("agent");
    new_result.push(':');
    new_result.push_str("30");

    // Capacity should be exact or very close
    assert!(new_result.capacity() <= size + 8); // Allow small overhead
}

/// Compare capacity growth: with vs without pre-sizing
#[test]
fn test_capacity_growth_comparison() {
    // Without pre-sizing: exponential growth
    let mut without = String::new();
    let mut without_caps = vec![without.capacity()];
    for c in "a]b:c:d:e:f:g:h".chars() {
        without.push(c);
        if without.capacity() != *without_caps.last().unwrap() {
            without_caps.push(without.capacity());
        }
    }

    // With pre-sizing: single allocation
    let with = String::with_capacity(15);
    let with_cap = with.capacity();

    println!("Without pre-sizing, capacity changes: {:?}", without_caps);
    println!("With pre-sizing: capacity = {}", with_cap);

    // Without: multiple capacity changes
    // With: single allocation
    assert!(without_caps.len() > 1);
}
