CURRENT COST:
```rust
fn search_hit_key_doc_id(key: &SearchHitKey) -> String {
    let sep = '\u{1f}';
    format!(
        "{}{sep}{}{sep}{}{sep}{}{sep}{}{sep}{}{sep}{}",
        key.source_id,
        key.source_path,
        key.conversation_id.map(|v| v.to_string()).unwrap_or_default(),   // heap alloc + drop
        key.title,
        key.line_number.map(|v| v.to_string()).unwrap_or_default(),        // heap alloc + drop
