fn detect_usernames(content: &str) -> Vec<UsernameMatch> {
    let mut matches = Vec::new();

    // Unix-style paths with usernames
    let home_regex = Regex::new(r"/home/([a-zA-Z][a-zA-Z0-9_\-]{0,31})/").unwrap();
    for cap in home_regex.captures_iter(content) {
        matches.push(UsernameMatch {
            username: cap[1].to_string(),
            full_match: cap[0].to_string(),
        });
    }

    // macOS paths
    let users_regex = Regex::new(r"/Users/([a-zA-Z][a-zA-Z0-9_\-]{0,31})/").unwrap();
    for cap in users_regex.captures_iter(content) {
        matches.push(UsernameMatch {
            username: cap[1].to_string(),
            full_match: cap[0].to_string(),
        });
    }

    // Windows paths
    let win_regex = Regex::new(r"C:\\Users\\([a-zA-Z][a-zA-Z0-9_\-]{0,31})\\").unwrap();
    for cap in win_regex.captures_iter(content) {
        matches.push(UsernameMatch {
            username: cap[1].to_string(),
            full_match: cap[0].to_string(),
        });
    }

    matches
}

fn detect_hostnames(content: &str) -> Vec<HostnameMatch> {
    // SSH-style host references, URLs, etc.
    let patterns = [
        r"(?i)hostname\s*[:=]\s*([a-zA-Z0-9\.\-]+)",
        r"@([a-zA-Z0-9\.\-]+):",  // user@host:
        r"//([a-zA-Z0-9\.\-]+):", // scheme://host:port
    ];

    // ... implementation
}
