fn test_full_reindex_performance() {
    let temp_dir = setup_large_test_index(10_000);

    // Measure single-insert time
    let start_single = Instant::now();
    reindex_single_insert(&temp_dir).unwrap();
    let single_duration = start_single.elapsed();

    // Reset and measure batch-insert time
    clear_fts5_index(&temp_dir).unwrap();

    let start_batch = Instant::now();
    let stats = reindex_with_batching(&temp_dir).unwrap();
    let batch_duration = start_batch.elapsed();

    println!("Performance comparison:");
    println!("  Single insert: {:?}", single_duration);
    println!("  Batch insert: {:?}", batch_duration);
    println!("  Speedup: {:.1}x", single_duration.as_secs_f64() / batch_duration.as_secs_f64());

    // Should be at least 10% faster
    assert!(batch_duration < single_duration * 9 / 10,
        "Batch insert should be at least 10% faster");
