## UTF-8 Safety Analysis
The current tokenizer normalizes to ASCII/lowercase before n-gram generation.
However, we should handle edge cases:

```rust
#[test]
fn test_utf8_safety() {
    // ASCII - direct slicing safe
    let ascii_ngrams = edge_ngrams_stack("hello");
    assert_eq!(ascii_ngrams.len(), 3); // "hel", "hell", "hello"

    // Multi-byte UTF-8 - must not slice mid-character
    let utf8_ngrams = edge_ngrams_stack("héllo"); // é is 2 bytes
    // Should produce valid strings, not panic
    for ngram in &utf8_ngrams {
        assert!(ngram.is_ascii() || ngram.chars().count() >= 3);
    }

    // CJK - each char is 3 bytes
    let cjk_ngrams = edge_ngrams_stack("你好世界");
    for ngram in &cjk_ngrams {
        assert!(std::str::from_utf8(ngram.as_bytes()).is_ok());
    }
}
