      - name: Upload corpus
        uses: actions/upload-artifact@v4
        with:
          name: corpus-${{ matrix.target }}
          path: fuzz/corpus/${{ matrix.target }}

      - name: Upload crashes
        if: failure()
        uses: actions/upload-artifact@v4
        with:
